[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$RequestPath,[string]$OutputPath='', [string]$AiSolutionPath='', [string[]]$RoundPaths=@())
$ErrorActionPreference='Stop'
# candidate-only: preflight cannot authorize writes or final completion; P0_DESIGN_NOT_ACCEPTED is the hard rejection marker.
$root=[IO.Path]::GetFullPath((Get-Location).Path).TrimEnd('\')+'\'
function Resolve-RootPath([string]$p){$f=if([IO.Path]::IsPathRooted($p)){[IO.Path]::GetFullPath($p)}else{[IO.Path]::GetFullPath((Join-Path (Get-Location) $p))};if(-not $f.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){throw 'Path outside project root.'};$f}
$solutionContractRel='ES/Automation/Contracts/es-ai-web-solution-response-v1.schema.json'
$solutionContractFile=Resolve-RootPath $solutionContractRel
if(-not (Test-Path -LiteralPath $solutionContractFile -PathType Leaf)){throw 'BLOCKED_WEB_PREFLIGHT_SOLUTION_CONTRACT_MISSING'}
$solutionContractHash=(Get-FileHash -LiteralPath $solutionContractFile -Algorithm SHA256).Hash.ToLowerInvariant()
$req=Resolve-RootPath $RequestPath;$r=Get-Content -Raw -Encoding UTF8 $req|ConvertFrom-Json
if(@($RoundPaths).Count -ne 5){$continuityOk=$false;$continuityJson='BLOCKED_WEB_PREFLIGHT_ROUND_PATHS_REQUIRED'}else{$continuityScript=Join-Path $root 'ES/Automation/WebPageStudio/Test-ESWebRoundContinuityGate.ps1';$continuityJson=& $continuityScript -RequestPath $req -RoundPaths $RoundPaths 2>&1 | Out-String;$continuityOk=$LASTEXITCODE -eq 0}
$skillRefs='.agents/skills/es-web-ui-generation-orchestration/references'
$stepIntent=Join-Path $skillRefs 'step-01-intent-analysis.md';$stepKnowledge=Join-Path $skillRefs 'step-02-knowledge-synthesis.md';$stepCapability=Join-Path $skillRefs 'step-03-capability-analysis.md';$stepIA=Join-Path $skillRefs 'step-04-information-architecture.md';$stepInteraction=Join-Path $skillRefs 'step-05-interaction-design.md';$stepVisual=Join-Path $skillRefs 'step-06-visual-responsive-design.md';$stepHtml=Join-Path $skillRefs 'step-07-html-materialization.md';$stepQuality=Join-Path $skillRefs 'step-08-quality-closeout.md'
$st=[Collections.Generic.List[object]]::new();function Add-Stage($id,$ok,$detail,$refs=@(),$analysis='',$execution=''){ $refsOk=$true;foreach($ref in @($refs)){if(-not (Test-Path (Join-Path $root $ref) -PathType Leaf)){ $refsOk=$false }};$priorBlocked=@($st|? status -eq 'blocked').Count -gt 0;$effectiveOk=$ok -and $refsOk -and (-not $priorBlocked);$status=if($effectiveOk){'passed'}else{'blocked'};if(-not $refsOk){$detail="required reference missing; $detail"};if($priorBlocked -and $ok){$detail="upstream stage blocked; execution is not permitted; $detail"};$toolAnalysis=if([string]::IsNullOrWhiteSpace($analysis)){"Tool validation for $id used bounded project scripts and referenced files."}else{$analysis};$toolExecution=if([string]::IsNullOrWhiteSpace($execution)){"Execute $id with deterministic checks; no AI design decision is inferred."}else{$execution};$st.Add([ordered]@{stage=$id;status=$status;aiAnalysis=$null;toolAnalysis=$toolAnalysis;toolExecution=$toolExecution;aiEvidenceRequired=$true;returnReceipt=[ordered]@{status=$status;detail=$detail;observable=($effectiveOk -and -not [string]::IsNullOrWhiteSpace($detail));blockedByUpstream=$priorBlocked;referencesVerified=$refsOk};detail=$detail;sourceRefs=@($refs)}) }
	Add-Stage 'round-continuity' $continuityOk $continuityJson @('ES/Automation/WebPageStudio/Test-ESWebRoundContinuityGate.ps1')
	$semanticContinuityOk=$false;$semanticContinuityJson='BLOCKED_WEB_PREFLIGHT_SEMANTIC_CONTINUITY_REQUIRED'
	if(@($RoundPaths).Count -eq 5){$semanticValidator=Join-Path $root 'ES/Automation/WebPageStudio/Test-ESWebRoundSemanticContinuity.ps1';if(Test-Path -LiteralPath $semanticValidator -PathType Leaf){$semanticRoundPaths=@($RoundPaths|Select-Object -First 4);$semanticContinuityJson=& $semanticValidator -RoundPaths $semanticRoundPaths -ProjectRoot $root 2>&1|Out-String;$semanticContinuityOk=$LASTEXITCODE -eq 0}}
	Add-Stage 'round-semantic-continuity' $semanticContinuityOk $semanticContinuityJson @('ES/Automation/WebPageStudio/Test-ESWebRoundSemanticContinuity.ps1')
	$intentOk=(-not [string]::IsNullOrWhiteSpace([string]$r.objective))-and(-not [string]::IsNullOrWhiteSpace([string]$r.primaryAction));Add-Stage 'intent-review' $intentOk 'objective, audience and primary action are explicit' @($stepIntent)
